/** Existing heating backup guide, verified source-specific candidates, no catalog mutation. */
function solar_expert_heating_ups_offers_v1($content) {
    if(is_admin() || !is_singular('post') || !in_the_loop() || !is_main_query() || !is_string($content) || strlen($content)>600000) return $content;
    $post=get_queried_object();
    if(!($post instanceof WP_Post) || $post->post_name!=='zalozni-zdroj-pro-obehove-cerpadlo' || strpos($content,'data-se-heating-ups-offers-v1')!==false) return $content;
    $pattern='~<h2(?:\s[^>]*)?>\s*LiFePO₄, AGM a automatické nabíjení: co zkontrolovat před koupí\s*</h2>~u';
    if(preg_match_all($pattern,$content,$m,PREG_OFFSET_CAPTURE)!==1) return $content;
    $bases=get_option('solar_expert_affiliate_bases',array());
    $base=is_array($bases)&&isset($bases['vselektro-eu'])&&is_string($bases['vselektro-eu'])?$bases['vselektro-eu']:'';
    $u=wp_parse_url($base); $query=array();
    if(is_array($u)&&isset($u['query'])) parse_str($u['query'],$query);
    $approved=is_array($u)&&($u['scheme']??'')==='https'&&($u['host']??'')==='ehub.cz'&&($u['path']??'')==='/system/scripts/click.php'&&!isset($u['user'])&&!isset($u['pass'])&&!isset($u['port'])&&is_string($query['a_aid']??null)&&is_string($query['a_bid']??null)&&preg_match('/^[a-zA-Z0-9_-]+$/D',$query['a_aid'])&&preg_match('/^[a-zA-Z0-9_-]+$/D',$query['a_bid']);


    $rows=array(
      array('vselektro-ups-800e-55ah','55 Ah · AGM','032011302','zalozni-zdroj-500w-sinus-zz22-plus-aku-55ah/','5,6 h','2,6 h','Menší rezerva pro kratší výpadky. Při celkovém odběru 40 W v našem modelu nestačí na osm hodin.'),
      array('vselektro-ups-800e-120ah','120 Ah · GEL','032011206','zalozni-zdroj-500w-sinuspro-800e-plus-aku-120ah/','12,1 h','5,7 h','Větší energetická rezerva; dvanáct hodin při 40 W je pouze hraniční model pro novou baterii.')
    );
    $block='<section data-se-heating-ups-offers-v1="1" aria-labelledby="se-heating-ups-offer-title" style="margin:22px 0;padding:clamp(16px,4vw,24px);background:#eff8f5;color:#142e2b;border:1px solid #c9ddd9;border-radius:16px;line-height:1.6"><p style="margin:0;color:#205d53;font-weight:700;font-size:.85em;text-transform:uppercase">Nákupní průvodce · záloha topení</p><h2 id="se-heating-ups-offer-title" style="margin:8px 0;color:#142e2b">Jaký záložní zdroj s baterií prověřit pro oběhové čerpadlo?</h2><p><strong>Pro 40W celkový odběr a osm hodin výpadku vychází v níže uvedeném modelu přibližně 80 Ah olověné baterie při 12 V. Pro 100W odběr přibližně 169 Ah.</strong> Nejde o garantovanou kapacitu pro kotel. Záložní zdroj musí být výrobcem kotle povolený, včetně chování při přepnutí, rozběhu a poruše.</p><div style="padding:12px;background:#fff;border:1px solid #c9ddd9;border-radius:10px"><strong>Společný zdroj VOLT SinusPRO 800 E (3SP080012E):</strong> 500 W trvale, 800 VA krátkodobě, čistý sinus při napájení z baterie, přepnutí nejvýše 4 ms a 12V olověná baterie. Výrobce výslovně nepovoluje připojit LiFePO₄ k této řadě. Upozorňuje také na možné obrácení polarity výstupu při přechodu na baterii; to je důvod nechat kompatibilitu zejména s fázově citlivým kotlem potvrdit odborníkem. <a href="https://voltpolska.pl/produkty/sinus-pro-800-e-12-230v-500-800w-zasilacz-awaryjny/" rel="noopener">Parametry výrobce</a>.</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px;margin-top:12px">';
    foreach($rows as $r) {
        $target='https://www.vselektro.eu/'.$r[3]; $href=$target;
        if($approved) $href='https://ehub.cz/system/scripts/click.php?'.http_build_query(array('a_aid'=>$query['a_aid'],'a_bid'=>$query['a_bid'],'desturl'=>$target),'','&',PHP_QUERY_RFC3986);
        $block.='<div style="background:#fff;border:1px solid #c9ddd9;border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:8px"><strong style="font-size:1.1rem">'.esc_html($r[1]).'</strong><small>SinusPRO 800 E + baterie</small><span style="font-size:1.35rem;font-weight:700;color:#205d53">'.esc_html($r[4]).' při 40 W</span><small>Při 100 W modelově '.esc_html($r[5]).'</small><p style="margin:0">'.esc_html($r[6]).'</p><small>Kat. č. '.esc_html($r[2]).' · Cena a sklad k ověření</small><a class="se-btn se-btn-primary" style="margin-top:auto" href="'.esc_url($href).'" data-se-deal-id="'.esc_attr($r[0]).'" data-se-merchant="vselektro-eu" data-se-placement="heating_ups_editorial_offers" data-se-monetized="'.($approved?'true':'false').'" rel="sponsored nofollow noopener">Ověřit cenu a dostupnost →</a></div>';
    }
    $block.='</div><p style="font-size:.9em">Dvě konkrétní sestavy z veřejných produktových výpisů VSelektro; nejde o srovnání celého trhu. Aktuální sklad ani ceny nejsou potvrzené. Odkazy mohou být partnerské; nákup za podmínek programu může přinést provizi.</p><h3 style="color:#142e2b">Výdrž 24, 55 a 120 Ah při různém odběru</h3><p>Pro tento odlišný model olověných baterií použijeme 12 V nominálně, 50 % využitelné energie, 90 % hypotetickou účinnost přeměny a 15 W modelové vlastní spotřeby (prodejce u řady uvádí 1,25 A bez zátěže; 12 V × 1,25 A = 15 W). Jde o konzervativní ilustrační rozklad ztrát, nikoli naměřenou účinnost při dané zátěži. Baterie dodává 40 / 0,90 + 15 ≈ 59,4 W nebo 100 / 0,90 + 15 ≈ 126,1 W.</p><div role="region" aria-label="Modelová doba zálohy" tabindex="0" style="overflow-x:auto;background:#fff;border:1px solid #c9ddd9;border-radius:10px"><table style="width:100%;min-width:430px;margin:0"><thead><tr style="background:#205d53;color:#fff"><th scope="col">12V baterie</th><th scope="col">Model využitelných Wh</th><th scope="col">40 W AC</th><th scope="col">100 W AC</th></tr></thead><tbody><tr><th scope="row">24 Ah</th><td>144</td><td>2,4 h</td><td>1,1 h</td></tr><tr><th scope="row">55 Ah</th><td>330</td><td>5,6 h</td><td>2,6 h</td></tr><tr><th scope="row">120 Ah</th><td>720</td><td>12,1 h</td><td>5,7 h</td></tr></tbody></table></div><p>Při 80 % původní kapacity by 120Ah baterie ve stejném modelu při 40 W poskytla už jen asi 9,7 hodiny. Reálný odběr, vybíjecí charakteristika, stav nabití, teplota a stárnutí výsledek mění. Nepoužívejte 50 % jako výrobcem schválenou hloubku vybití bez kontroly bateriové dokumentace. Pro plánování 24 hodin při 40 W vychází asi 238 Ah, tedy mimo tyto dvě nabízené varianty; ověřte odborně navrženou alternativu, nikoli improvizované paralelní propojení.</p><h3 style="color:#142e2b">Co si nechat potvrdit před objednáním</h3><p>Vyžádejte si přesné označení zdroje a akumulátoru, odpovídající nabíjecí proud, bezpečnou instalaci, podporu kotle při přepnutí, garantované či měřené trvání zálohy při skutečném odběru a postup kontrol po instalaci. U kotle na tuhá paliva musí být nezávisle zajištěna předepsaná ochrana před přehřátím. Baterie nenahrazuje dochlazovací smyčku ani jiné výrobcem požadované ochrany.</p><p><a class="se-btn" href="/vyber-baterii/">Přepočítat energetickou rezervu →</a> <a class="se-btn" href="/vyber-menice/">Prověřit napětí a výkon →</a></p></section>';
    $offset=$m[0][0][1];
    return substr($content,0,$offset).$block.substr($content,$offset);
}
